    (167, 'SABRINA MULLER', '', null, '', 'um clt nosso chamado andre monteiro trouxe a para dentro do nosso hostel.. mas ela nao esta aqui hospedada...', date '2017-08-12', 'Lisb''on Hostel'),
    (168, 'Raul Raiz', 'Espanhol', date '1976-07-27', 'BI - 04602017Q', 'Homem moreno . Entra no quarto e leva tudo o que tiver por lá!', date '2017-08-15', 'Good Morning Hostel'),
    (169, 'OTHMAN BEN LARBI', 'Holandes', null, 'P - NYBBLJ980', 'assediou fisicamente uma outra hóspede no hostel', date '2017-08-21', 'Lisbon Landscape Hostel'),
    (170, 'Stan Onwu', 'Nigeriano', null, '326190', 'nigeriano  com atitude k nao se pode..', date '2017-08-24', 'Lisboa Hub new Hostel'),
    (171, 'Iara Alexandra Dias Gaspar e Tania Sofia Campos Botelho Dias', '', null, '', 'mãe e filha problemáticas. Informação dada pela pousada da juventude, roubaram malas de outros hospedes', date '2017-08-31', 'HUB Lisbon Patio Hostel'),
    (172, 'David Portillo', 'Espanhol', null, '', 'Foi apanhado de manhã a lamber (literalmente) um pote de nutela que tinha sido colocado para o pequeno almoço. Como foi apanhado em flagrante, ficou envergonhado, e acabou por ir comprar um pote novo. ... justiça seja feita.Mais tarde descobrimos que fanou 3 rolos de papel higiénico dos wc''s.', date '2017-09-05', 'Lisbon Landscape Hostel'),
    (173, 'Raul Ruiz Lozano', 'Espanhol', null, '', 'Spanish guy who checked in 2 days ago with us. he probably stole 2 laptops and he didn´t return to the hostel yesterday although he had a reservation', date '2017-09-12', 'Oasis Backpackers´ Mansion Lisboa'),
    (174, 'Paulo Varela', '', null, 'rapaz moreno, alto', 'Há suspeitas de q ele furtou um tablet', date '2017-10-08', 'Lisbon Landscape Hostel Landscape'),
