    (177, 'Pedro Nogueira', 'Portugues', null, '11554325', 'mal educado e ordinário com os membros femininos do staff (borderline abusador).', date '2017-10-17', 'HUB Lisbon Patio Hostel'),
    (178, 'Fausto Pires', 'Angolano', null, '', 'esteve cá ontem a tentar ficar sem pagar. Ele tem 4/5 cartões e nenhum deles funciona. Diz que vai levantar mas que as máquinas não têm dinheiro', date '2017-10-27', 'Hub New Lisbon hostel'),
