    (182, 'OTTO Pessoa', 'Brasileiro', null, '', 'Suspeito de furto não fez nada demais aqui porque eu estava sempre em cima dele, fazia check out sempre.. sempre depois da hora.- é desagradável e desrespeitador.', date '2017-12-10', 'Lisb''on Hostel & Lookout Lisbon'),
    (183, 'Teresa Manuel Ferreira Ryder da Costa', 'portuguesa - diz que é de Tomar', null, '', 'história que está em Lisboa acompanhando um parente que está no hospital. E depois vai embora sem pagar - sem malas, sem cartões e sem bi', date '2017-12-15', 'Lisbon Old Town Hostel/Shiado Hostel'),
    (184, 'Joana Ferreira/Joana Stevan', 'Portuguesa - de Cascais', null, 'born in 1988 / with a big black luggage/sbut she looks yunger /she was reserving through hostel world - loira', 'acting really weird and had no money - comportamento bastante suspeito e é pouco higiénica..', date '2017-12-16', 'Oasis Backpackers'),
    (185, 'Muhammad Naeem', 'Paquistão', null, 'Tem dois passaportes com o mesmo numero mas nomes diferentes', 'Aparecia só à noite para dormir, às vezes não tinha o valor da reserva todo e deixou a mala aqui por uns dias e só voltou para buscar depois - não paga', date '2017-12-21', 'Lisbon Old Town Hostel/ Surf in Chiado Hostel/Shiado Hostel'),
    (186, 'Svea Schlageter', '', null, 'deve ter uns 39 anos, alta, loira  mas está sempre com uma cara de aborrecida', 'Ela esteve aqui uns 5 dias e começou a arranjar problemas com outros hóspedes, a gritar e algumas vezes ameaças', date '2018-01-06', 'Safestay Lisboa'),
