    (193, 'André Filipe Gil Prino', 'Portugues', date '1992-04-15', 'BI 218501870-É português e de aparência pouco suspeita, ''''é bonito e carismático''''', 'bebe desmesuradamente, consome droga o dia e noite inteiros, tentou molestar uma cliente e furtou 300 euros de outro', date '2018-01-21', 'Surf''in Chiado Hostel'),
    (194, 'Kristoffer Thomsen', 'dinamarca,', null, '40 anos - tem cabelo comprido apanhado,', 'omeçou a ser super rude e mal educado para o staff.. a dizer asneiras e a convidar as mulheres para sair.', date '2018-01-22', 'Lisboa Central Hostel'),
    (195, 'Pedro Gaspar Serras Pereira', 'portugues', null, '40 anos', 'Não tinha BI, disse que foi roubado, mostrou o registro da polícia, disse que não sabia se ia ficar, depois ligou disse que estava com pouco dinheiro, disse que ia buscar outro sítio, acabou por voltar, fez o check in, ficou 5 minutos no quarto e agora saiu dizendo que tem uma prima aqui que talvez possa hospeda-lo', date '2018-01-22', 'Lisboa Old Town'),
    (196, 'Rui Manuel Monteiro de Carvalho', 'Portugues', date '1971-11-30', '40 anos* ver foto', 'roubou telemovel e parece estranho', date '2018-01-24', 'Oasis Backpackers´ Mansion Lisboa'),
    (197, 'Vanessa Tapia e Jorge Miguel Garcia Diaz', 'Mexicanos', null, '', 'Um casal mexicano que esteve mais de uma vez no Safestay, ambas as vezes usufruindop de uma cama com apenas uma reserva. Desta ssegunda vez, fomos mais severos e alertamos que a segunda pessoa deveria pagar. Eles nos atribuiram uma bad review mentirosa,de cunho pessoal e ofensivo, sendo que eles saíram do hostel sem pagar a noite desta segunda pessoa, sem fazer check out ou entregar as chaves.', date '2018-02-01', 'Safestay Lisboa'),
    (198, 'Paulo Damasceno', 'Brasil, vive na Madeira', null, '', 'Foi muito mal educado com outros clientes , recepcionista e um dos gerentes.', date '2018-02-04', 'Lisbon Landscape Hostel Landscape'),
    (199, 'Svea Schlageter', 'suécia', null, '', 'completamente maluca,ela tinha uma reserva de 7 dias aqui, mas só ficou um e resolveu ir embora,', date '2018-02-05', 'Lookout Lisbon'),
    (200, 'Rafael Rama', 'Portugal', null, '', 'ma pessoa absolutamente descontrolada. Trata muito mal , as pessoas , difícil de pagar e insistir fumar ganzá dentro do hostel e usar a casa de banho feminina . Quase agride as pessoas . Tivemos de chamar as autoridades para abandonar o hostel.', date '2018-02-15', 'Lisbon Landscape Hostel Landscape'),
    (201, 'Akim Sahnoun', 'Frances', null, 'ver foto*', 'comportamento reservado, rapaz educado, sempre pagou a estadia, não criou problemas com ninguém, aparentemente um clinte normal mas a policia do aeroporto de Lisboa ligou porque o apreenderam no aeroporto e trasnportou-o para um hospital - suspeita-se de sofrer de algum caso de paronoia ou doença mental estava descontrolado ao ponto de ter de ser apreendido (Agente Celso Marques)', date '2018-02-24', 'Living Lounge Hostel'),
    (202, 'Alexandre Carvalho Fernandes', 'dupla nacionalidade', date '1974-01-26', '151013217', 'faz-se acompanhar de um rapaz mais novo e roubou o dinheiro aos restantes hospedes de um dormitório inteiro', date '2018-02-26', 'Inn Possible Hostel'),
    (203, 'Carlos carvalho', 'br com bi pt', null, '', 'muito mal educado a fazer coisas improprias nu no dormitorio com outros hospedes a tentarem dormir', date '2018-03-04', 'HUB Lisbon Patio Hostel'),
    (204, 'Rafael Rama', 'pt', null, '', 'trabalha na UBER.. é mto má pessoa!! Trata mto mal aos hóspedes e ao Staff', date '2018-03-04', 'Lisbon Landscape Hostel Landscape'),
    (205, 'Antonio Almeida', 'pt - 50 anos', null, '', 'entrou ontem a noite mas acabamos por expulsa-lo porque começou a mexer nas coisas dos outros hospedes. Completamente bêbado e caiu a porta do Hostel. chamamos a ambulância e seguiu', date '2018-03-22', 'Music hall Lisbon'),
    (206, 'Chris Benstead, James Crawley-Boevey, Damien Cody,Joshua Eden', 'ingleses', null, '', 'Pessoal, atenção a um grupo de ingleses que anda por aí! São um total de 4 e acabamos de expulsar 2 do nosso hostel', date '2018-03-30', 'Lisbon patio hostel'),
    (207, 'ORLANDO MANUEL ANTÃO', '', null, '', 'foi rude e agressivo com o staff e ainda tentou ficar indevidamente com o depósito da chave que pedimos!', date '2018-04-09', 'SAFESTAY LISBOA (Equity point)'),
    (208, 'Jorge Ampuero
