    (475, 'Luis António Batista', 'Francês', null, '', 'Atenção Porto e Matosinhos - Hospede: Luis António Batista, com cartão identidade francês, mas é português. Furtou 2 máquinas fotográficas profissionais, 2 lentes e alguns objetos em prata e cobre. Arrombou um armário e dissimulou o arrombamento. Está acompanhado por 2 adolescentes e pela mãe -Henriqueta Batista. Aconteceu hoje em Matosinhos. Reserva via Booking', date '2024-08-23', 'D. Odete'),
    (476, 'Henriqueta Batista', '', null, '', 'Atenção Porto e Matosinhos - Hospede: Luis António Batista, com cartão identidade francês, mas é português. Furtou 2 máquinas fotográficas profissionais, 2 lentes e alguns objetos em prata e cobre. Arrombou um armário e dissimulou o arrombamento. Está acompanhado por 2 adolescentes e pela mãe -Henriqueta Batista. Aconteceu hoje em Matosinhos. Reserva via Booking', date '2024-08-23', 'D. Odete'),
    (477, 'ALEKSANDER PACANOWSKI', 'Polónia', null, '', 'O hóspede foi-se embora do meu alojamento sem pagar! Voltou para me dizer na cara que não ia pagar (aparentemente ja deve ter feito noutros sitios pois sabe as leis e sabe que nada lhe acontece....) e eu nada posso fazer a não ser apresentar uma queixa na polícia mas visto que o hóspede é Polaco e não tem morada cá vai ser muito difícil. Atenção a todos os colegas. Ele está em Lisboa, Ericeira, Peniche por aí...', date '2024-09-25', 'D. Odete'),
    (478, 'SHAUN ANDERSON', 'Estados Unidos da América', date '1978-09-27', '668848601', 'Confusa/maluca, suspeita de roubar outra hóspede que estava no mesmo quarto. Conhecida como "miss miss"', date '2024-09-29', 'LCH'),
    (479, 'Ali Mumbasar', 'Paquistão', null, 'BZ1796034', 'Assediador, agressivo, alcoólatra', date '2025-01-26', 'Miguel'),
    (480, 'CHITO KALOMBO JOAO', 'Angola', date '1982-11-27', 'N1989000', 'Fez CO mas as malas ficaram no Hostel // hóspede veio buscar as malas - não aceitar mais reservas ou estender', date '2025-02-01', 'LCH'),
    (481, 'DOMINGOS KALUNGA QUITUMBA', 'Angola', date '1976-02-04', 'N7775495', 'Não fez CO. esposa ligou 22:20 a avisar que só vem amanhã buscar as malas. cobrar valor das malas e pegar a chave do quarto - nao deixar reservar mais // veio buscar as malas e pagou', date '2025-02-01', 'LCH'),
    (482, 'DIAMANTINO GABRIEL TECA BENTO', 'Brasil', date '1982-11-25', 'GK592232', 'Senhor rude, não queria pagar a reserva que tinha ativa, alegando que estava a espera de "PIX" , teve uma atitude rude com o tiago, e até ameaçou a "defesa " do consumidor', date '2025-03-08', 'LCH'),
    (483, 'HELENA MARIA DE CAMPOS SILVA', 'Portugal', date '1981-02-12', '118635514', 'Chata, suspeita de roubar tenis de outro hespede. Depois do CO deixo 7 malas no storage durante 11 noites a pesar de muitas advertncias', date '2025-01-01', 'LCH'),
    (484, 'Paulo César Narciso', 'Portugal', null, '', 'Rachelle Kiki
Ja tive este sr.. fez reserva para 6, tiveram 16.. estragaram me a casa toda e o booking nao fez nada! Na altura ainda nao trabalhava com caução.. de qualquer maneira 1000€ nao chegou para os danos que ele me fez.. tivemos de comprar um sofa e almofadas novo!', date '2025-01-01', 'Grupo AL'),
    (485, 'Ericson Balde', '', null, '', 'Deixou apartamento airbnb em um estado assustador', date '2025-01-01', 'Grupo AL'),
    (486, 'paul denis burke', 'GBR', date '1959-06-12', '142740528', 'Chegou bêbado ao hostel, não sendo respeitoso com o staff e outros hóspedes. Nem sequer conseguia chegar ao próprio quarto.', date '2025-05-19', 'LCH'),
    (487, 'Wu Ling', '', null, '', 'Cuidado com o hóspede Wu ling. reservou para 2 pessoas, apareceram 3. Como não temos capacidade recusamos a 3 pessoa. A partir daí foi reclamação atrás de reclamação. Lençóis sujos, sendo que eram novos e estavam impecáveis. Hoje exigiram mudança de toalhas, recusamos pois só mudamos a cada 7 dias. Passaram para as mensagens desagradáveis a dizer que estava tudo imundo e que iam dar má cotação. Perguntei o que queriam visto ser infundado e que se quisessem podiam sair. Querem o reembolso… - CUIDADO já reportado a booking', date '2025-05-23', 'D. Odete'),
    (488, 'Hamed Kourtit', 'Holanda', null, 'BFK72DL23', 'entrou aqui no hostel e roubou um monte de cacifos', date '2025-05-26', 'Miguel'),
    (489, 'giseli machado pedroso', 'Brasil', date '1991-05-15', 'gg229378', 'Comportamento estranho , entrou no quarto tomou banho,depois pediu reembolso porque não se sentia a vontade para ficar por ter ouvido a gritar fogo quando estava na casa de banho , pediu rembolso parcial foi negado , aceitou bem mas não esteve mais que 25 minutos no hostel', date '2025-08-06', 'LCH'),
    (490, 'ALEXANDER MANFRED HELM GRIEBL', 'Alemanha', date '1995-10-20', 'LFXZN3L14', 'Chegou aparentemente drogado, não encontrava sua chave, perguntou sobre um pote com maconha e disse que havia perdido sua carteira de motorista. Levei o Hóspede ao quarto e o mesmo retornou, foi á cozinha, pegou a tesoura do hostel e colocou dentro de sua bolsa. eu intervi e o fiz devolver.// pediu para fazer early check-out hoje(30/08) pois perdeu seus pertences pessoais que estavam no locker ( drogas, carteiras, dinheiro), reclamou que foi cobrado varias vezes o valor da chave perdida do locker quando ainda nem tinha sido cobrado// Perdeu a carteira no quarto logo apos pagar a chave mas gonçalo encontrou debaixo da cama extra// Cortou o fio do termometro do frigorifico e retirou umas pilhas, alegou que nao foi ele quando o tomas o viu a tirar o termometro que estava sumido do bolso e por na mesa dizendo que o encontrou//Foi expulso pelo tomas //hospede ligou a dizer que o encontrou na rua a ter uma overdose, espumando da boca e a tentar vender drogas a pessoas na rua perto do hostel. Fui a procura dele pelo quarteirao mas nao o encontrei.// foi expulso do hostel 19:00, estava drogado e tentou roubar termometro frigorifico do staff', date '2025-01-01', 'LCH'),
    (491, 'paulo nunes nicolau trincão henriques', 'Portugal', date '1993-02-10', '145460525', 'APANHADO A ROUBAR NO CHILLOUT HOSTEL - Chillout informou o Miguel por mensagem e ligou para aqui para a receção para verificar se estaria cá // esteve cá a 12/10/2025/Roubou notas na parede do Hostel - LCH - 13/10', date '2025-10-19', 'Chillout Hostel / LCH'),
    (492, 'Faouzi Mokhtrai', 'Argélia', date '1993-06-12', '156301330', 'Efetuou varios roubos e trouxe as coisas para dentro do Hostel. Foi levado pela policia', date '2025-10-20', 'Informado por Miguel'),
    (493, 'Mohamed Kourtit', 'Marrocos', date '1996-11-26', 'rw3834583', 'Principal suspeito de um furto a um hóspede no Sunset Destination. Nada apurado, mas fez walkin só para a noite de hoje. Depois da vítima se queixar à recepção,  o suspeito tinha o seu cacifo desocupado e a cama designada estava praticamente intacta  (lençóis quase nem mexidos). Encontra-se ausente da propriedade. Avisamos de forma prévia, caso tenham algum walkin desta pessoa ainda hoje ou no futuro.', date '2025-10-31', 'Informado por Miguel'),
    (494, 'Cathal Griffin', 'Irlanda', date '1985-08-21', 'PV6199900', 'Bom dia, cuidado com este indivíduo, tem comportamentos “estranhos” e tem uma violência verbal muito evidente. Está no Porto', date '2025-11-17', 'Informado por Miguel'),
    (495, 'Elijah Davis', 'Reino Unido', date '1987-06-14', '157695761', 'Hóspede confuso, mau aspecto, maluco , late check-out, confuso', date '2025-11-19', 'Decisão do tiago'),
    (496, 'IRINA ALEXANDRA PEREIRA CABRITA', 'Portugal', date '1998-08-28', '15949607', 'Insistiu em ficar em quarto com mais gente possível, staff achou estranho, então pus sozinha, ela saiu hoje. Pessoa estranha, claramente a procura de ´oportunidades´ (email da miliante: Irinacabrita62@gmail.com)', date '2025-11-28', 'Enviado via whatsapp pelo Miguel'),
    (497, 'EMANUEL MYRON WINKLER', 'Alemanha', date '2000-12-02', 'C1CHF55WM', 'Ficou hospedado no Avenue por longo periodo mas cancelaram a possibilidade de estender a reserva pela booking por conta do mal aspecto. Ja identificamos o hospede a dormir na rua, ele é estranho, aparencia mal cuidada, entra e sai muitas vezes do hostel, quando ficou, foi aloado em quarto sozinho mas de certeza que ira incomodar outros hospedes com movimentação.', date '2025-11-27', ''),
    (498, 'Alexandre Carvalho Fernandes', 'Brasil', date '1974-01-26', 'GD058041', 'Fez check-in, saiu e não voltou. Roubou carteira doutro hóspede', date '2026-01-16', 'Enviado via whatsapp pelo Miguel'),
    (499, 'Edmilsson  da Conceição António Araújo', '', null, '', 'Foi denunciado por fraude em hósteis por Lisboa', date '2026-01-01', ''),
