    (505, 'Manuel Oliveira', '', null, '', 'Reservam todos em separado mas montem festa juntos... Muito alcohol, chatices. Tentam trazer malta de fora etc etc', date '2026-01-01', ''),
    (506, 'Juan Pedro gallado', 'Espanha', date '1954-12-06', '52510380T', 'Senhor apesar de simpático, já de idade, têm problemas de incontinencia, e têm sempre um cheiro forte a urina, na ultima estadia (11/02 a 14/02 , alguns hóspedes queixaram-se )', date '2026-02-14', ''),
    (507, 'Anabela dos Santos Silva Tavares', 'Portugal', date '1953-09-06', '028517962zx6', 'Aldrabona, nao paga a horas, inventora de historias, temos de estar sempre atras, vem com sacos de pingo doce , ede dinheiro a outros hospedes para pagar reservas', date '2026-02-26', ''),
    (508, 'GEORGE CATALIN JULA', 'Roménia', date '1989-08-23', '066103552', 'Homem romeno/taliano, chegou com umas histórias que talvez não dormisse no hostel, ganhou free upgrade e queixo-se, fez questão de voltar para quarto de 10 pax, e na manhã seguinte outro hóspede foi furtado dinheiro, possivelmente ele', date '2026-03-02', 'Informado por Miguel/LCH'),
    (509, 'ORNELIO Hinterholz Junior', 'italia?', date '1982-06-15', '', 'provavelmente uso de drogas pesadas, andou nu , discurso estranho com outros hospedes', date '2026-03-05', 'Informado por Miguel'),
    (510, 'Lidia Sorbello', 'australia', null, 'PB4134036', 'Hospede extremamente mal educada, agressiva, não respeita outros guest e nem staff.', date '2026-03-06', 'Informado por Miguel /Expulsa do Patio'),
    (511, 'FILOMENO ALEXANDRE RAMOS PANDA', 'ANGOLA', date '1997-12-10', 'N2697079', 'Hóspede, faz sempre CO tarde, não atende telefone, age um pouco como se estivessem em casa, dia 10/03, também teve uma atitude suspeita, com o telefone do gonçalo que desapareceu , mas o hóspede comentou que "tinha só sido esquecido e caido", quando até estava desligado', date '2026-03-15', 'Nuno Colocou'),
    (512, 'Darlene Donszelmann', 'Canada', null, 'P424855NW', 'Hospede problemática, gritava na receção, disse que não podia com cheiros de produtos de limpeza, trocamos de quarto e as manutenções eram feitas com produtos sem odor e mesmo assim reclamava. Ficava com a porta do quarto aberta e reclama do barulho e de outros hospedes por passar na frente do quarto.', date '2026-03-16', 'Informado por Miguel'),
    (513, 'Lukas Griffin', 'USA', null, 'F2793415', 'Hospede reservou para duas pessoas e eram 4 pessoas, rude e grosseiro, não respeitou as regras. Fez chantagens dizendo que queria refund se não faria review negativa. Histórico do hospede no Airbnb é de ser problemático em varios alojamentos que já passou.', date '2026-03-16', 'Informado por Miguel'),
    (514, 'Ana Teixeira', 'Brasil', date '1962-12-15', 'YD1054246', 'Hóspede um pouco esquisita, usa como mala, um carrinho de compras do pingo doce, a reserva foi feita por uma pessoa terceira , acumulou comida durante o pequeno almoço, foi chamada a atenção e não gostou, adicionada aos a evitar', date '2026-03-16', 'Nuno Colocou'),
    (515, 'Bruno Miguel Da Silva Rodrigues', 'Portugal', null, 'CC 128309989', 'Suspeito de roubo no Pátio na noite de 30/01/26. Hóspedes relataram que o viram na madrugada a revirar bagagens alheias e sentiram falta de algumas roupas pela manhã.', date '2026-01-01', ''),
    (516, 'NUNO ALEXANDRE GOMES BARBOSA', 'Portugal', date '1985-01-06', '128103019', 'Maluco, rude e ofensivo para com o staff', date '2026-04-08', 'Lisboa Central Hostel'),
    (517, 'Mohamed Mella', 'França', null, '58771', 'Realizaram reserva para 2 hóspedes, mas ficaram 4 pessoas, quando confrontados, negaram! Fumaram no interior do alojamento, com queixas de vizinhos e evidências no alojamento.', date '2026-04-09', 'D.Odete'),
    (518, 'Nell Emma Anseline', 'França', null, '55913', 'Realizaram reserva para 2 hóspedes, mas ficaram 4 pessoas, quando confrontados, negaram! Fumaram no interior do alojamento, com queixas de vizinhos e evidências no alojamento.', date '2026-04-09', 'D.Odete'),
    (519, 'Ricardo José Coelho Magalhães Pescada', 'Portugal', null, 'NIF 208162488/Carta de condução FA 2244537', 'Chamámos a polícia porque ele estava agressivo e recusava-se a sair do hostel. A polícia informou-nos que outros hostels já tinham apresentado queixas contra ele; não é a primeira vez', date '2026-04-22', 'Miguel'),
    (520, 'RICKY HEENEMANN', 'Suiça', date '2005-08-31', 'K0U68B24', 'Está a assediar o hostel, com emails e ligações na recepção a falar coisas inapropriadas', date '2026-04-26', 'Miguel'),
    (521, 'Matthias Bulnes', 'Chile', null, '21DC19873', 'violento tivemos de chamar a polícia para o expulsar. Lisboa', date '2026-05-16', 'Miguel')
),
normalized as (
  select
    row_order,
    trim(name) as name,
    trim(nationality) as nationality,
    birth_date,
    upper(regexp_replace(trim(doc_number), '\s+', '', 'g')) as doc_number,
    trim(what_happened) as what_happened,
    occurrence_date,
    trim(who_reported) as who_reported
  from source_rows
),
filtered as (
  select *
  from normalized
  where occurrence_date is not null
    and (coalesce(name, '') <> '' or coalesce(doc_number, '') <> '')
),
deduped as (
  select distinct on (
    lower(coalesce(name, '')),
    coalesce(doc_number, ''),
    occurrence_date,
    lower(coalesce(who_reported, '')),
    lower(coalesce(what_happened, ''))
  )
    *
  from filtered
  order by
    lower(coalesce(name, '')),
    coalesce(doc_number, ''),
    occurrence_date,
    lower(coalesce(who_reported, '')),
    lower(coalesce(what_happened, '')),
    row_order desc
)
insert into public.guests_blacklist (
  name,
  nationality,
  nationality_code,
  birth_date,
  doc_number,
  what_happened,
  occurrence_date,
  who_reported
)
select
  coalesce(name, ''),
  coalesce(nationality, ''),
  '',
  birth_date,
  coalesce(doc_number, ''),
  coalesce(what_happened, ''),
  occurrence_date,
  coalesce(who_reported, '')
from deduped d
where not exists (
  select 1
  from public.guests_blacklist g
  where lower(coalesce(g.name, '')) = lower(coalesce(d.name, ''))
    and upper(regexp_replace(coalesce(g.doc_number, ''), '\s+', '', 'g')) = coalesce(d.doc_number, '')
    and g.occurrence_date = d.occurrence_date
    and lower(coalesce(g.who_reported, '')) = lower(coalesce(d.who_reported, ''))
    and lower(coalesce(g.what_happened, '')) = lower(coalesce(d.what_happened, ''))
);
